export function evaluate({ inputs, time, seed, state }) {
  const launchSpeed = inputs.launchSpeed ?? 4.0;
  const gravity = inputs.gravity ?? 9.8;

  const apexTime = launchSpeed / gravity;
  const apexHeight = (launchSpeed * launchSpeed) / (2 * gravity);

  // time is elapsed time from start. Let's make time = 0 be the start (launch height at t=0, so time goes from 0 to 2*apexTime approx).
  // Wait, the plan timeline says durationSeconds ~ 1.666, and displayOffset is negative apexTime, meaning time ranges from 0 to 2*apexTime.
  // Let's define t as elapsed time from start:
  const t = Math.max(0, Math.min(time, 2 * apexTime));

  const tossHeight = launchSpeed * t - 0.5 * gravity * t * t;
  const tossedVelocity = launchSpeed - gravity * t;
  const tossedAcceleration = -gravity;

  // Drop ball: held at apexHeight until t >= apexTime, then falls from apexHeight
  const dropped = t >= apexTime;
  const dropHeight = dropped ? apexHeight - 0.5 * gravity * Math.pow(t - apexTime, 2) : apexHeight;
  const dropVelocity = dropped ? -gravity * (t - apexTime) : 0;
  const dropAcceleration = dropped ? -gravity : 0;

  // States for lanes
  let tossState = "At launch";
  if (t > 0.05 && t < apexTime - 0.05) tossState = "Rising";
  else if (Math.abs(t - apexTime) <= 0.05) tossState = "At the top";
  else if (t > apexTime + 0.05 && tossHeight > 0.05) tossState = "Falling";
  else if (t >= apexTime && tossHeight <= 0.05) tossState = "At launch height";

  let dropState = "Held in place";
  if (Math.abs(t - apexTime) <= 0.05) dropState = "Just released";
  else if (t > apexTime + 0.05 && dropHeight > 0.05) dropState = "Falling together";
  else if (t >= apexTime && dropHeight <= 0.05) dropState = "At launch height";

  // Frame objects setup
  // Width 640, Height 420
  // Two lanes: Toss lane at x: 40, w: 260. Drop lane at x: 340, w: 260.
  // Height scale: 0 to 2.2 m mapped to y from 350 (height 0) up to 90 (height 2.2).
  const hToY = (h) => 350 - (h / 2.2) * 260;

  const objects = [];

  // Lanes
  objects.push(...sdk.panel({ x: 30, y: 50, w: 270, h: 330, title: "Toss lane", state: tossState, id: "lane.toss" }));
  objects.push(...sdk.panel({ x: 330, y: 50, w: 270, h: 330, title: "Drop lane", state: dropState, id: "lane.drop" }));

  // Axes inside lanes (place them carefully to avoid overlaps)
  objects.push(sdk.axis("axis.toss", { x: 50, y: 350, length: 260, orientation: "y", min: 0, max: 2.2, ticks: [0, 1.0, 2.0], label: "h", unit: "m" }));
  objects.push(sdk.axis(
    "axis.drop",
    {
      x: 350,
      y: 350,
      length: 260,
      orientation: "y",
      min: 0,
      max: 2.2,
      ticks: [0, 1.0, 2.0],
      label: "h",
      unit: "m"
    }
  ));

  // Ground marks
  objects.push(sdk.groundMark("mark.toss", 160, 350, 80, "Launch"));
  objects.push(sdk.groundMark("mark.drop", 460, 350, 80, "Launch"));

  // Release gate at apexHeight in Drop lane
  const gateY = hToY(apexHeight);
  objects.push(sdk.gate("gate", 460, gateY, { open: dropped, label: "Gate" }));

  // Balls
  const tossBallY = hToY(Math.max(0, tossHeight));
  const dropBallY = hToY(Math.max(0, dropHeight));

  objects.push(sdk.circle("ball.toss", 160, tossBallY, 24, { role: "output" }));
  objects.push(sdk.circle("ball.drop", 460, dropBallY, 24, { role: "output" }));

  // Vectors: velocity (blue), acceleration (dashed warm)
  // Shift vectors to the sides to avoid overlap with ticks and gate
  objects.push(sdk.vector("vec.v.toss", { x: 120, y: tossBallY }, { value: tossedVelocity, direction: "up" }, { scale: 20, label: "v" }));
  objects.push(sdk.vector("vec.a.toss", { x: 200, y: tossBallY }, { value: tossedAcceleration, direction: "up" }, { scale: 10, label: "a" }));

  objects.push(sdk.vector("vec.v.drop", { x: 420, y: dropBallY }, { value: dropVelocity, direction: "up" }, { scale: 20, label: "v" }));
  objects.push(sdk.vector("vec.a.drop", { x: 500, y: dropBallY }, { value: dropAcceleration, direction: "up" }, { scale: 10, label: "a" }));

  // Callouts
  objects.push(...sdk.callout(75, tossBallY - 20, [
    `v: ${tossedVelocity.toFixed(2)} m/s`,
    `a: ${tossedAcceleration.toFixed(1)} m/s^2`
  ], { id: "callout.toss" }));

  objects.push(...sdk.callout(375, dropBallY - 20, [
    `v: ${dropVelocity.toFixed(2)} m/s`,
    `a: ${dropAcceleration.toFixed(1)} m/s^2`
  ], { id: "callout.drop" }));

  return {
    frame: {
      width: 640,
      height: 420,
      objects,
      readouts: [
        { id: "tossedVelocity", value: tossedVelocity },
        { id: "tossedAcceleration", value: tossedAcceleration },
        { id: "dropVelocity", value: dropVelocity },
        { id: "dropAcceleration", value: dropAcceleration }
      ]
    },
    quantities: {
      launchSpeed,
      gravity,
      apexTime,
      apexHeight,
      tossedVelocity,
      tossedAcceleration,
      tossedHeight: tossHeight,
      dropVelocity,
      dropAcceleration,
      dropHeight
    }
  };
}
